var d=UnityEngine.Object.FindAnyObjectByType<DungeonPrototype>();var t=d.GetType();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;d.enabled=false;d.StopAllCoroutines();int checks=0;var logs=new System.Collections.Generic.List<string>();System.Action<bool,string> check=(ok,label)=>{checks++;if(!ok)throw new System.Exception(label);logs.Add(label);};var settings=RefugeSettings.Current;check((Vector2Int)t.GetField("position",f).GetValue(d)==settings.startCell,"New game starts in lower refuge corner");check((bool)t.GetProperty("IntroductionActive",f).GetValue(d,null),"Existing introduction remains active");t.GetMethod("ProcessIntroductionInput",f).Invoke(d,new object[]{false,true,0f});var world=(WorldDialogue)t.GetField("worldDialogue",f).GetValue(d);System.Action drain=()=>{for(int n=0;n<100&&world.Active;n++){world.CompleteLetters();world.Advance(35);}if(world.Active)throw new System.Exception("Dialogue did not close");};var state=(RefugeProgress)t.GetField("refuge",f).GetValue(d);check(!state.refugeTragedyTriggered&&!state.devotoDefeated,"Fresh event state");check(settings.npcs.Length==5&&DungeonRegionSettings.Current.At(settings.startCell).safeArea,"Five NPC and safe starting zone");foreach(var npc in settings.npcs){t.GetMethod("BeginNpcTalk",f).Invoke(d,new object[]{npc.id});check(world.Current.text==npc.conversations[0],"NPC first line "+npc.id);drain();t.GetMethod("BeginNpcTalk",f).Invoke(d,new object[]{npc.id});check(world.Current.text==npc.conversations[1],"NPC second line "+npc.id);drain();}t.GetField("hp",f).SetValue(d,2);DungeonSaveStore.editorTestPath=System.IO.Path.GetFullPath("Docs/Refuge-test-save.json");t.GetMethod("UseRefugeTerminal",f).Invoke(d,null);check(d.CapturePlayerProgression().currentHP==(int)t.GetProperty("MaximumHP",f).GetValue(d,null)&&System.IO.File.Exists(DungeonSaveStore.SavePath),"Terminal heals and writes isolated test save");drain();d.RegisterTransferNode("node.refuge");check(state.unlockedNodes