nged refuge");var loaded=DungeonSaveStore.Read();d.RestoreDungeonSave(loaded);state=(RefugeProgress)t.GetField("refuge",f).GetValue(d);check(state.refugeTragedyTriggered&&state.exitDialogueCompleted&&state.unlockedNodes.Count==2&&state.npcs.Find(n=>n.id=="centinela").lastWordsHeard&&!actors["centinela"].activeSelf,"Restore event nodes and body state from disk");objects=(System.Collections.Generic.List<GameObject>)t.GetField("enemyObjects",f).GetValue(d);boss=objects.FindIndex(o=>o!=null&&o.GetComponent<EnemyCombatStats>().placementId==settings.devotoPlacementId);check(boss>=0,"Devoto restored");t.GetMethod("BeginDevotoConversation",f).Invoke(d,null);check(world.lines.Length==9,"Devoto precombat dialogue");drain();check((bool)t.GetField("battle",f).GetValue(d),"Existing combat starts");System.IO.File.WriteAllText("Docs/PruebasRefugio.txt","PASS "+checks+" checks\n"+string.Join("\n",logs.ToArray()));return new{status="PASS",checks=checks,bossIndex=boss,savePath=DungeonSaveStore.SavePath};